import h3Sizes from '../../../functions/shared/minimaxH3ImageSizes.json';
import Seedream55Controls from './Seedream55Controls.jsx';
import { seedream55Settings } from '../lib/seedream55.js';
import { useEffect, useMemo, useState, useSyncExternalStore } from 'react';
import { ImagePlus, ListPlus } from 'lucide-react';
import { dllWorkspace, openDllWorkspace, DLL_LOCAL_ACCEPTANCE } from '../lib/dllWorkspaceRuntime.js';
import '../styles/generation.css';
import OpenAI26Controls from './OpenAI26Controls.jsx';
import { gifSizeLabel, imageCountOptions, isOpenAI26, openAI26Settings, OPENAI_26_DEFAULTS } from '../lib/openaiImage26.js';
import ComfyQuotaPanel from './ComfyQuotaPanel.jsx';
import { openVideoWorkspace, prepareVideoPng } from '../lib/comfyVideoClient.js';
import {
  DLL_PIC_ASPECT_RATIOS,
  KREA3_EXTRA_ASPECT_RATIOS,
  DLL_ASIAN_MIX_MODEL_KEYS,
  DLL_QWEN_MODEL_KEYS,
  DLL_PIC_STORAGE_KEYS,
  getDllPicApiKeyForModel,
  getDllPicApiKeyStorageKeys,
  getDllPicModelConfig,
  getDllPicLoraSelection,
  getDllPicLoraModelKey,
  getDllPicLoraSettings,
  readDllPicLoraStrength,
  getDllPicResolutionOption,
  getDllPicResolutionOptions,
  getDllPicSelectableModelEntries,
  isDllPicAspectRatioSupported,
  normalizeDllPicModelKey,
} from '../lib/dllPicProClient.js';
import { readComfyPending, clearComfyPending } from '../lib/comfyCloudProxyClient.js';
import { getComfyGenerationNote } from '../lib/dllPicGenerationPresentation.js';
import { downloadImageFile } from '../lib/imageDownload.js';
import { downloadMagnificImageViaFirebase } from '../lib/magnificProxyClient.js';

function loadStoredValue(key, fallback = '') {
  if (typeof window === 'undefined') return fallback;
  try {
    return window.localStorage.getItem(key) || fallback;
  } catch {
    return fallback;
  }
}

function loadStoredModelKey(fallback = 'google31FlashLiteImage') {
  return normalizeDllPicModelKey(loadStoredValue(DLL_PIC_STORAGE_KEYS.model, fallback), fallback);
}

function loadStoredLoraStrength(modelKey) {
  return readDllPicLoraStrength(modelKey, key => loadStoredValue(key));
}

function loadStoredApiKey(modelKey) {
  if (typeof window === 'undefined') return '';
  for (const key of getDllPicApiKeyStorageKeys(modelKey)) {
    const value = loadStoredValue(key);
    if (value) return value;
  }
  return '';
}

function saveStoredApiKey(modelKey, apiKey) {
  if (typeof window === 'undefined') return;
  const normalizedApiKey = apiKey.trim();
  getDllPicApiKeyStorageKeys(modelKey).forEach((key) => {
    try {
      if (normalizedApiKey) {
        window.localStorage.setItem(key, normalizedApiKey);
      } else {
        window.localStorage.removeItem(key);
      }
    } catch {
      // Ignore unavailable storage; generation still uses in-memory keys.
    }
  });
}

const DLL_PIC_API_KEY_FIELDS = [
  {
    provider: 'google',
    modelKey: 'google31FlashLiteImage',
    label: 'Gemini API Key',
    placeholder: '貼上 Google Gemini API Key',
  },
  {
    provider: 'xai',
    modelKey: 'xaiGrokImagineQuality',
    label: 'xAI API Key',
    placeholder: '貼上 xAI API Key',
  },
];

const DLL_PIC_PROXY_FIELDS = [
  {
    provider: 'comfyCloud', label: 'Comfy Cloud API Key', status: 'Firebase Secret',
    description: '由伺服端 COMFY_CLOUD_API_KEY 提供；請先登入 Firebase。',
  },
];

function loadStoredProviderApiKeys() {
  return DLL_PIC_API_KEY_FIELDS.reduce((keys, field) => ({
    ...keys,
    [field.provider]: loadStoredApiKey(field.modelKey),
  }), {});
}

function saveStoredGenerationSettings(modelKey, resolution) {
  if (typeof window === 'undefined') return;
  const modelConfig = getDllPicModelConfig(modelKey);

  try {
    window.localStorage.setItem(DLL_PIC_STORAGE_KEYS.model, modelKey);
    if (modelConfig.supportsResolution) {
      window.localStorage.setItem(DLL_PIC_STORAGE_KEYS.resolution, resolution);
    }
  } catch {
    // Ignore unavailable storage; current session state remains usable.
  }
}

function getGenerationErrorMessage(error) {
  if (typeof error === 'string') return error;
  return error?.message || error?.details || error?.code || '生成失敗';
}

function loadDevPreviewImages() {
  if (typeof window === 'undefined' || !import.meta.env.DEV) return [];
  const demoImageUrl = new URLSearchParams(window.location.search).get('dllPicDemoImage');
  return demoImageUrl ? [{ src: demoImageUrl, mimeType: 'image/jpeg' }] : [];
}

export default function DllPicProPanel({
  title = 'DLL_PIC Pro',
  description = '用目前 prompt 直接生成圖像並預覽結果。',
  promptSources = [],
  fullWorkspacePromptSources,
  defaultSourceId = '',
  compact = false,
  workspaceId = 'Prompt 工作台',
  full = false,
  onPickFace,
  initialSettings = {},
  onBringSources,
  sourceWorkspace,
}) {
  const availableSources = promptSources.filter((source) => source?.value?.trim());
  const initialSourceId = defaultSourceId || availableSources[0]?.id || promptSources[0]?.id || '';
  const shared = useSyncExternalStore(dllWorkspace.subscribe, dllWorkspace.getSnapshot);
  const sharedTask = [...shared.tasks].reverse().find(task => full ? task.id === shared.selected : task.snapshot.workspace === workspaceId);
  const [modelKey, setModelKey] = useState(() => normalizeDllPicModelKey(initialSettings.modelKey || loadStoredModelKey()));
  const [faceReference, setFaceReference] = useState(initialSettings.faceReference || '');
  const [faceError, setFaceError] = useState('');
  const hasFaceSupport = full && modelKey === 'comfySeedream5Pro';
  const [custom, setCustom] = useState(Boolean(initialSettings.custom));
  const [customPrompt, setCustomPrompt] = useState(initialSettings.customPrompt || '');
  const [seed, setSeed] = useState(initialSettings.seed ?? '');
  const [promptExpanded, setPromptExpanded] = useState(Boolean(initialSettings.custom));
  const [loraStrength, setLoraStrength] = useState(() => initialSettings.loraStrength ?? loadStoredLoraStrength(modelKey));
  const [apiKeys, setApiKeys] = useState(loadStoredProviderApiKeys);
  const [apiKeyDrafts, setApiKeyDrafts] = useState(loadStoredProviderApiKeys);
  const [isApiKeyModalOpen, setIsApiKeyModalOpen] = useState(false);
  const [selectedSourceId, setSelectedSourceId] = useState(initialSettings.selectedSourceId || initialSourceId);
  const [requestedAspectRatio, setAspectRatio] = useState(initialSettings.aspectRatio || (modelKey === 'comfyMinimaxH3Image' ? '1:1' : '9:16'));
  const aspectRatio = requestedAspectRatio;
  const [resolution, setResolution] = useState(() => (
    getDllPicResolutionOption(modelKey, initialSettings.resolution || loadStoredValue(DLL_PIC_STORAGE_KEYS.resolution, '1k')).value
  ));
  const [requestedCount, setCount] = useState(initialSettings.count || 1);
  const [quality, setQuality] = useState(initialSettings.quality || 'medium');
  const [openaiSettings, setOpenaiSettings] = useState(() => ({ ...OPENAI_26_DEFAULTS, ...Object.fromEntries(Object.keys(OPENAI_26_DEFAULTS).filter(key => initialSettings[key] !== undefined).map(key => [key, initialSettings[key]])) }));
  const [seedreamSettings, setSeedreamSettings] = useState(() => ({ background: initialSettings.background || 'auto', watermark: initialSettings.watermark ?? false, customWidth: initialSettings.customWidth ?? 2048, customHeight: initialSettings.customHeight ?? 2048, referenceImages: initialSettings.referenceImages || [] }));
  const [referenceBusy, setReferenceBusy] = useState(false);
  const is55 = modelKey === 'comfySeedream55';
  const [thinkingMode, setThinkingMode] = useState(initialSettings.thinkingMode || 'fast');
  const comfyPending = DLL_LOCAL_ACCEPTANCE ? null : readComfyPending();
  const [quickResult, setQuickResult] = useState(null);
  useEffect(() => {
    if (full || !sharedTask?.summaryOnly || !sharedTask.images.length) return;
    let active = true;
    dllWorkspace.readTask(sharedTask).then(task => {
      if (active) setQuickResult({ summary: sharedTask, images: task.images });
    }).catch(() => {});
    return () => { active = false; };
  }, [full, sharedTask]);
  const images = !full && sharedTask?.summaryOnly
    ? (quickResult?.summary === sharedTask ? quickResult.images : [])
    : sharedTask?.images || loadDevPreviewImages();
  const [selectedImageIndex, setSelectedImageIndex] = useState(0);
  const [previewImageIndex, setPreviewImageIndex] = useState(null);
  const [previewImageSize, setPreviewImageSize] = useState(null);
  const isGenerating = shared.busy;
  const [downloadingImageIndex, setDownloadingImageIndex] = useState(null);
  const [message, setMessage] = useState(() => (loadDevPreviewImages().length ? '已套用本地預覽圖' : ''));

  const activeModel = getDllPicModelConfig(modelKey);
  const countOptions = imageCountOptions(modelKey, openaiSettings.outputFormat);
  const count = countOptions.includes(requestedCount) ? requestedCount : 1;
  const is26 = isOpenAI26(modelKey);
  let openaiError = '';
  try { if (is26) openAI26Settings({ ...openaiSettings, quality, resolution }); } catch (error) { openaiError = error.message; }
  const loraSelection = getDllPicLoraSelection(modelKey);
  const loraLabel = loraSelection.label || 'MOSS LoRA';
  let loraSettings = {};
  let loraError = '';
  try { loraSettings = getDllPicLoraSettings(modelKey, loraStrength); }
  catch (error) { loraError = error.message; }
  const changeLoraStrength = value => {
    setLoraStrength(value);
    try {
      const valid = getDllPicLoraSettings(loraSelection.loraModelKey, value);
      window.localStorage.setItem(loraSelection.storageKey, String(valid.loraStrength));
    } catch { /* Keep incomplete input editable without persisting it. */ }
  };
  const activeResolution = getDllPicResolutionOption(modelKey, resolution).value;
  const activeResolutionOptions = getDllPicResolutionOptions(modelKey);
  const activeModelNote = activeModel.supportsResolution
    ? `${activeModel.generationModel} / ${activeModel.resolutionLabels?.[activeResolution] || activeResolution.toUpperCase()}`
    : activeModel.imageSize
      ? `${activeModel.generationModel} / ${activeModel.imageSize}`
      : activeModel.generationModel;
  const previewImage = previewImageIndex === null ? null : images[previewImageIndex] || null;
  const previewDisplaySize = previewImageSize ? {
    width: previewImageSize.width / 2,
    height: previewImageSize.height / 2,
  } : null;
  const selectedSource = useMemo(() => (
    promptSources.find((source) => source.id === selectedSourceId) || availableSources[0] || promptSources[0] || null
  ), [availableSources, promptSources, selectedSourceId]);
  const selectedPrompt = full && custom ? customPrompt : selectedSource?.value || '';
  let seedreamError = '';
  try { if (is55) seedream55Settings({ ...seedreamSettings, resolution: activeResolution, aspectRatio }); } catch (error) { seedreamError = error.message; }
  const snapshot = () => ({ ...(is55 ? { ...seedreamSettings, ...seedream55Settings({ ...seedreamSettings, resolution: activeResolution, aspectRatio }) } : {}), modelKey, ...(hasFaceSupport && faceReference ? { faceReference } : {}), ...getDllPicLoraSettings(modelKey, loraStrength), prompt: selectedPrompt, aspectRatio, resolution: activeResolution, count, quality, thinkingMode, ...(is26 ? openAI26Settings({ ...openaiSettings, quality, resolution: activeResolution }) : {}),
    seed: (full || is55) && activeModel.provider === 'comfyCloud' ? seed : '', sourceId: custom ? 'custom' : selectedSource?.id,
    sourceLabel: custom ? '自訂' : selectedSource?.label, workspace: workspaceId, lockAspectRatio: Boolean(selectedSource?.lockAspectRatio) });
  const draftSignature = JSON.stringify({ sources: promptSources, modelKey, loraStrength, selectedSourceId, aspectRatio, resolution: activeResolution, count, thinkingMode, ...(is55 ? { ...seedreamSettings, referenceImages: undefined } : {}), ...(is26 ? openaiSettings : {}), quality, custom, customPrompt, seed, workspaceId });
  useEffect(() => { if (full && shared.ready) dllWorkspace.draft({ ...JSON.parse(draftSignature), faceReference, ...(is55 ? { referenceImages: seedreamSettings.referenceImages } : {}) }); }, [full, shared.ready, draftSignature, faceReference, is55, seedreamSettings.referenceImages]);
  const isAspectRatioLocked = Boolean(selectedSource?.lockAspectRatio && selectedSource?.aspectRatio);
  const isAspectRatioSupported = isDllPicAspectRatioSupported(modelKey, aspectRatio);
  const invalidLockedSize = (is55 && isAspectRatioLocked && activeResolution === 'custom') || is26 && isAspectRatioLocked && (['auto', 'custom'].includes(activeResolution) || openaiSettings.outputFormat === 'gif');
  const activeApiKey = getDllPicApiKeyForModel(modelKey, apiKeys);
  const canGenerate = Boolean(
    (DLL_LOCAL_ACCEPTANCE || activeModel.usesServerProxy || activeApiKey)
    && selectedPrompt.trim()
    && activeModel.generationModel
    && isAspectRatioSupported
    && !loraError
    && !openaiError && !seedreamError && !referenceBusy
    && !invalidLockedSize
    && shared.ready
    && !isGenerating
    && !(activeModel.provider === 'comfyCloud' && comfyPending)
  );
  const modelCompatibilityNote = isAspectRatioSupported
    ? ''
    : KREA3_EXTRA_ASPECT_RATIOS.some(option => option.value === aspectRatio)
      ? `目前模型不支援 ${aspectRatio}，請選擇支援的比例。`
      : `目前模型不支援固定 ${aspectRatio}，請改用 Google Gemini Nano Banana 2 Lite`;

  useEffect(() => {
    if (selectedSource?.aspectRatio) setAspectRatio(selectedSource.aspectRatio);
  }, [selectedSource?.aspectRatio, selectedSource?.id]);

  const openApiKeyModal = () => {
    setApiKeyDrafts(apiKeys);
    setIsApiKeyModalOpen(true);
  };

  const closeApiKeyModal = () => {
    setIsApiKeyModalOpen(false);
    setApiKeyDrafts(apiKeys);
  };

  const saveApiKeys = () => {
    const nextApiKeys = DLL_PIC_API_KEY_FIELDS.reduce((keys, field) => {
      const normalizedApiKey = (apiKeyDrafts[field.provider] || '').trim();
      saveStoredApiKey(field.modelKey, normalizedApiKey);
      return {
        ...keys,
        [field.provider]: normalizedApiKey,
      };
    }, {});

    setApiKeys(nextApiKeys);
    setApiKeyDrafts(nextApiKeys);
    setIsApiKeyModalOpen(false);
    setMessage('DLL_PIC Pro API Keys 已保存');
  };

  const openImagePreview = (index) => {
    setSelectedImageIndex(index);
    setPreviewImageSize(null);
    setPreviewImageIndex(index);
  };

  const closeImagePreview = () => {
    setPreviewImageIndex(null);
    setPreviewImageSize(null);
  };

  const handleGenerate = async () => {
    setMessage('');
    try {
      saveStoredGenerationSettings(modelKey, activeResolution);
      await dllWorkspace.enqueue(snapshot(), true);
    } catch (error) { setMessage(getGenerationErrorMessage(error)); }
  };
  const handleResumeComfy = async () => {
    try { await dllWorkspace.recoverLegacy(comfyPending); }
    catch (error) { setMessage(getGenerationErrorMessage(error)); }
  };

  const handleDownloadImage = async (src, index) => {
    setDownloadingImageIndex(index);
    try {
      await downloadImageFile({
        src,
        index,
        remoteDownload: downloadMagnificImageViaFirebase,
      });
    } catch (error) {
      setMessage(getGenerationErrorMessage(error));
    } finally {
      setDownloadingImageIndex(null);
    }
  };

  useEffect(() => {
    if (!previewImage) return undefined;

    const handleKeyDown = (event) => {
      if (event.key === 'Escape') setPreviewImageIndex(null);
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [previewImage]);

  useEffect(() => {
    if (!isApiKeyModalOpen) return undefined;

    const handleKeyDown = (event) => {
      if (event.key === 'Escape') {
        setIsApiKeyModalOpen(false);
        setApiKeyDrafts(apiKeys);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [apiKeys, isApiKeyModalOpen]);

  const loraVariants = Object.values(DLL_QWEN_MODEL_KEYS).includes(modelKey)
    ? [[DLL_QWEN_MODEL_KEYS.lora, 'v1.3b LoRA'], [DLL_QWEN_MODEL_KEYS.omni, 'Omni LoRA']]
    : Object.values(DLL_ASIAN_MIX_MODEL_KEYS).includes(modelKey)
      ? [[DLL_ASIAN_MIX_MODEL_KEYS.lora, 'Asian Mix LoKr'], [DLL_ASIAN_MIX_MODEL_KEYS.radiance, 'Radiance LoRA']]
      : null;
  const loraControls = <>
        {loraVariants ?
          loraVariants.map(([variant, label]) =>
            <label className="dll-pic-lora-control" key={variant}>
              <input type="checkbox" aria-label={`套用 ${label}`} checked={modelKey === variant} disabled={!full && isGenerating}
                onChange={event => {
                  const nextModelKey = event.target.checked ? variant : loraSelection.modelKey;
                  setModelKey(nextModelKey);
              if (nextModelKey === 'comfyMinimaxH3Image' && !isAspectRatioLocked) setAspectRatio('1:1');
                  setLoraStrength(loadStoredLoraStrength(nextModelKey));
                  saveStoredGenerationSettings(nextModelKey, activeResolution);
                }} />
              <span>套用 {label}</span>
            </label>) : loraSelection.supported && <label className="dll-pic-lora-control">
          <input type="checkbox" aria-label={`套用 ${loraLabel}`} checked={loraSelection.enabled} disabled={!full && isGenerating}
            onChange={event => {
              const nextModelKey = getDllPicLoraModelKey(modelKey, event.target.checked);
              setModelKey(nextModelKey);
              if (nextModelKey === 'comfyMinimaxH3Image' && !isAspectRatioLocked) setAspectRatio('1:1');
              saveStoredGenerationSettings(nextModelKey, activeResolution);
            }} />
          <span>套用 {loraLabel}{!loraSelection.adjustable && <small>強度 {loraSelection.strength}</small>}</span>
        </label>}
        {loraSelection.adjustable && loraSelection.enabled && <div className="dll-pic-lora-strength">
          <span>{loraSelection.strengthLabel}</span>
          <div className="dll-pic-lora-strength-inputs">
            <input type="range" aria-label={`${loraSelection.strengthLabel}滑桿`} min="0" max="1" step="0.05" value={typeof loraStrength === 'number' ? loraStrength : loraSelection.strength}
              disabled={!full && isGenerating} onChange={event => changeLoraStrength(Number(event.target.value))} />
            <input type="number" aria-label={`${loraSelection.strengthLabel}數值`} min="0" max="1" step="0.05" value={loraStrength}
              disabled={!full && isGenerating} onChange={event => changeLoraStrength(event.target.value === '' ? '' : Number(event.target.value))} />
          </div>
          <small>0–1，每次調整 0.05。{loraSelection.hint}</small>
          {loraError && <small className="dll-pic-quota-error" role="alert">{loraError}</small>}
        </div>}
  </>;

  return (
    <>
      {full && <div className="dll-generation-bar" aria-label="生成操作">
        <div className="dll-generation-buttons">
          <button className="primary-copy-btn dll-pic-generate-btn" type="button" onClick={handleGenerate} disabled={!canGenerate}><ImagePlus size={18} />{isGenerating ? '生成中...' : '生成圖像'}</button>
          <button type="button" className="secondary" disabled={!selectedPrompt.trim() || !shared.ready || !isAspectRatioSupported || Boolean(loraError) || Boolean(openaiError) || Boolean(seedreamError) || referenceBusy || invalidLockedSize} onClick={async () => { try { await dllWorkspace.enqueue(snapshot()); setMessage('已加入待生成清單'); } catch (error) { setMessage(error.message); } }}><ListPlus size={18} />加入待生成</button>

        </div>
        <p className="dll-generation-summary">{activeModel.label} · {is55 && activeResolution === 'custom' ? `${seedreamSettings.customWidth} × ${seedreamSettings.customHeight}` : is26 && openaiSettings.outputFormat === 'gif' ? `${gifSizeLabel(openaiSettings.gifSize)}（GIF）` : is26 && activeResolution === 'auto' ? '自動尺寸' : is26 && activeResolution === 'custom' ? `${openaiSettings.customWidth} × ${openaiSettings.customHeight}` : `${aspectRatio} · ${activeModel.resolutionLabels?.[activeResolution] || activeResolution.toUpperCase()}`} · {count} 張{activeModel.provider === 'openai' && ` · 畫質：${{ auto: '自動', low: '低', medium: '中', high: '高', xhigh: '超高', max: '最高' }[quality]}`}</p>
        {faceReference && <p className="dll-face-summary"><img src={faceReference} alt="" />{hasFaceSupport ? '已套用臉部參考' : '此模型不會使用臉部參考'}</p>}
        <p className="dll-generation-context">{custom ? '自訂 Prompt' : selectedSource?.label || '尚未帶入來源'}{activeModel.provider === 'comfyCloud' && ` · Seed：${seed === '' ? '隨機' : seed}`}{loraSelection.enabled && ` · ${loraLabel} ${loraSelection.adjustable ? loraStrength : loraSelection.strength}`}</p>
        {(modelCompatibilityNote || loraError || openaiError || invalidLockedSize || !selectedPrompt.trim() || comfyPending || (!DLL_LOCAL_ACCEPTANCE && !activeModel.usesServerProxy && !activeApiKey)) && <p className="dll-generation-notice" role="status">{modelCompatibilityNote || loraError || openaiError || (invalidLockedSize ? '來源已固定比例，請選擇 1K 或 2K 靜態圖片。' : '') || (!selectedPrompt.trim() ? '請先帶入來源或編輯本次 Prompt。' : comfyPending ? '請先查詢上次 Comfy 任務，再開始生成。' : '請先在 API Keys 設定此模型的金鑰。')}</p>}
        {activeModel.provider === 'comfyCloud' && !DLL_LOCAL_ACCEPTANCE && !loraError && <ComfyQuotaPanel compact modelKey={activeModel.comfyModel} {...loraSettings} {...(is55 ? { customWidth: seedreamSettings.customWidth, customHeight: seedreamSettings.customHeight, referenceCount: seedreamSettings.referenceImages.length } : {})} resolution={activeResolution} aspectRatio={aspectRatio} refreshToken={images} />}
      </div>}
    <section className={`dll-pic-panel ${full ? 'dll-full-settings' : ''} ${compact ? 'dll-pic-panel-compact' : ''}`} aria-label={title} aria-description={description}>
      <div className="dll-pic-header">
        <div>
          <div className="control-section-title">{title}</div>
        </div>
        <div className="dll-pic-header-actions">
          {!full && <button type="button" className="secondary" onClick={() => openDllWorkspace({ sources: fullWorkspacePromptSources ?? promptSources, settings: { modelKey, loraStrength, selectedSourceId, aspectRatio, resolution: activeResolution, count, thinkingMode, ...openaiSettings, ...(is55 ? seedreamSettings : {}), seed, quality }, workspaceId, taskId: sharedTask?.id })}>開啟完整版</button>}
          <button className="secondary dll-pic-api-settings-btn" type="button" onClick={openApiKeyModal}>
            API Keys
          </button>
        </div>
      </div>

      <div className="dll-pic-settings-grid">
        {!full && <label className="field dll-pic-field">
          <select
            aria-label="Prompt 來源"
            className={!selectedPrompt ? 'select-muted' : ''}
            value={selectedSource?.id || ''}
            disabled={!full && isGenerating}
            onChange={(event) => { setSelectedSourceId(event.target.value); setCustom(false); }}
          >
            {promptSources.map((source) => (
              <option key={source.id} value={source.id} disabled={!source.value?.trim()}>
                {source.label}
              </option>
            ))}
          </select>
        </label>}

        <label className="field dll-pic-field">
          {full && <span>模型</span>}
          <select
            aria-label="模型"
            value={loraSelection.modelKey}
            disabled={!full && isGenerating}
            onChange={(event) => {
              const nextModelKey = event.target.value;
              if (!isOpenAI26(nextModelKey) && !['low', 'medium', 'high'].includes(quality)) setQuality('medium');
              const nextResolution = ['comfySeedream55', 'comfyMinimaxH3Image'].includes(nextModelKey) ? '2k' : getDllPicResolutionOption(nextModelKey, resolution).value;
              setModelKey(nextModelKey);
              if (nextModelKey === 'comfyMinimaxH3Image' && !isAspectRatioLocked) setAspectRatio('1:1');
              setLoraStrength(loadStoredLoraStrength(nextModelKey));
              setCount(1);
              setSeed('');
              setResolution(nextResolution);
              saveStoredGenerationSettings(nextModelKey, nextResolution);
            }}
          >
            {getDllPicSelectableModelEntries().map(([key, model]) => (
              <option key={key} value={key}>
                {model.label}
              </option>
            ))}
          </select>
        </label>

        {hasFaceSupport && <div className="dll-face-field">
          <strong>臉部參考圖（選用）</strong>
          <div className="dll-row">
            {faceReference && <img src={faceReference} alt="已選臉部參考圖" />}
            <label className="secondary dll-file-button">{faceReference ? '更換' : '上傳圖片'}
              <input type="file" aria-label="上傳臉部參考圖" accept="image/jpeg,image/png,image/webp" onChange={async event => {
                const file = event.target.files?.[0];
                event.target.value = '';
